SELECT m.p, m.fb FROM (SELECT 1 AS a, 2 AS v, 3 AS p) MATCH_RECOGNIZE (PARTITION BY p ORDER BY a MEASURES FIRST(v) AS fb, MATCH_NUMBER() AS mn, ARRAY_AGG(CLASSIFIER()) AS c, LAST(v) AS lv, COUNT(*) AS n AFTER MATCH SKIP TO NEXT ROW PATTERN (^ X+ Y? | Z{2,3} $) DEFINE X AS v > PREV(v), Y AS v < 5, Z AS v = 1) AS m WHERE m.fb > 0 ORDER BY m.p
